-- =====================================================================
-- FinvQuant PostgreSQL V74：sys schema 新增系统用户表 sys.sys_user
--
-- 决策（ACANX 2026-10-25）：
--   - 需求：系统用户表落在 V71 新建的 sys schema，与 sys_config（V72）、
--     sys_dict / sys_dict_sub（V73）同属系统域；表结构按 ACANX 提供的 DDL
--     落地，列类型、默认值、可空性、约束名与列注释保持一致。
--   - 主键 idn 使用 IDENTITY（GENERATED BY DEFAULT AS IDENTITY），
--     允许显式插入指定值（数据迁移场景需要），并复用 V72/V73 的时间口径：
--     gmt_create 只在插入时生成，更新不改写。
--   - 初值对齐原库 AUTO_INCREMENT=1028：空表时序列 RESTART WITH 1028；
--     若表中已有数据（手工重跑或先灌了种子），改为把序列推到 max(idn)+1，
--     避免重复执行 RESET 造成主键冲突。整个判断幂等。
--   - 唯一约束：email、mobile_phone_no 各自唯一（PostgreSQL 允许多行 NULL，
--     与 MySQL 唯一索引语义一致）。
--   - 逻辑删除由 flag_delete 承担（'1' 已删除 / '0' 未删除），不做物理删除。
--   - 无物理外键（与全库「禁止外键、关系由应用层校验」一致）。
--   - 幂等：CREATE SCHEMA/TABLE IF NOT EXISTS + CREATE OR REPLACE FUNCTION +
--     触发器存在性判断 + COMMENT 覆盖写。
-- 迁移策略：单事务、失败整体回滚；末尾做收敛校验。
-- 前置：V71（sys schema）、V72、V73 已应用。
-- =====================================================================

BEGIN;

-- ---------------------------------------------------------------------
-- 1. schema 兜底（V71 已创建；此处幂等，便于单文件手工执行）
-- ---------------------------------------------------------------------
CREATE SCHEMA IF NOT EXISTS sys;

-- ---------------------------------------------------------------------
-- 2. 系统用户表
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS sys.sys_user (
    idn                 bigint       GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    uin                 bigint       DEFAULT NULL,
    uid                 varchar(32)  NOT NULL,
    avatar              varchar(4000) DEFAULT NULL,
    nick_name           varchar(32)  NOT NULL,
    id_cn               varchar(64)  DEFAULT NULL,
    id_cn_name          varchar(255) DEFAULT NULL,
    password            varchar(128) NOT NULL,
    password_salt       varchar(64)  NOT NULL,
    email               varchar(64)  NOT NULL,
    mobile_phone_no     varchar(32)  DEFAULT NULL,
    description         text         DEFAULT NULL,
    user_control_str    varchar(128) DEFAULT NULL,
    authority_str       varchar(6000) NOT NULL DEFAULT '0',
    region              varchar(64)  DEFAULT NULL,
    intl_tele_area_code varchar(16)  DEFAULT NULL,
    language            varchar(16)  DEFAULT 'zh-CN',
    time_zone           varchar(16)  DEFAULT 'UTC+08:00',
    gmt_create          timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    gmt_modify          timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    flag_delete         char(1)      DEFAULT '0',
    pass                varchar(255) DEFAULT NULL,
    create_by           varchar(32)  DEFAULT NULL,
    modify_by           varchar(32)  DEFAULT NULL,
    CONSTRAINT pk_sys_user PRIMARY KEY (idn),
    CONSTRAINT uk_sys_user_email UNIQUE (email),
    CONSTRAINT uk_sys_user_mobile UNIQUE (mobile_phone_no)
);

-- 对齐原表 AUTO_INCREMENT=1028（幂等：空表才重启序列，有数据则接续 max+1）
DO $$
DECLARE
    seq     TEXT;
    lastv   BIGINT;
    maxid   BIGINT;
BEGIN
    SELECT pg_get_serial_sequence('sys.sys_user', 'idn') INTO seq;
    IF seq IS NULL THEN
        RAISE NOTICE 'V74: sys_user.idn 不是 identity/序列列，跳过初值设置';
        RETURN;
    END IF;

    SELECT max(idn) INTO maxid FROM sys.sys_user;
    EXECUTE format('SELECT last_value FROM %s', seq) INTO lastv;

    IF maxid IS NULL AND lastv < 1028 THEN
        EXECUTE 'ALTER TABLE sys.sys_user ALTER COLUMN idn RESTART WITH 1028';
        RAISE NOTICE 'V74: 空表，sys_user.idn 序列初值对齐 1028';
    ELSIF maxid IS NOT NULL AND maxid >= lastv THEN
        PERFORM setval(seq, maxid + 1, false);
        RAISE NOTICE 'V74: 表已有数据，sys_user.idn 序列接续 max(idn)+1 = %', maxid + 1;
    ELSE
        RAISE NOTICE 'V74: 序列已就绪（last_value=%），不调整', lastv;
    END IF;
END $$;

-- ---------------------------------------------------------------------
-- 3. 表与列注释
-- ---------------------------------------------------------------------
COMMENT ON TABLE  sys.sys_user                    IS '系统用户表';
COMMENT ON COLUMN sys.sys_user.idn                IS '主键（自增）';
COMMENT ON COLUMN sys.sys_user.uin                IS '用户数字账号';
COMMENT ON COLUMN sys.sys_user.uid                IS '用户ID';
COMMENT ON COLUMN sys.sys_user.avatar             IS '用户图像';
COMMENT ON COLUMN sys.sys_user.nick_name          IS '昵称';
COMMENT ON COLUMN sys.sys_user.id_cn              IS '身份证号';
COMMENT ON COLUMN sys.sys_user.id_cn_name         IS '姓名';
COMMENT ON COLUMN sys.sys_user.password           IS '密码';
COMMENT ON COLUMN sys.sys_user.password_salt      IS '密码盐';
COMMENT ON COLUMN sys.sys_user.email              IS '注册邮箱';
COMMENT ON COLUMN sys.sys_user.mobile_phone_no    IS '手机号码';
COMMENT ON COLUMN sys.sys_user.description        IS '用户备注';
COMMENT ON COLUMN sys.sys_user.user_control_str   IS '用户权限控制串';
COMMENT ON COLUMN sys.sys_user.authority_str      IS '用户权限';
COMMENT ON COLUMN sys.sys_user.region             IS '地区';
COMMENT ON COLUMN sys.sys_user.intl_tele_area_code IS '国际电话区号';
COMMENT ON COLUMN sys.sys_user.language           IS '本地化语言';
COMMENT ON COLUMN sys.sys_user.time_zone          IS '所在时区';
COMMENT ON COLUMN sys.sys_user.gmt_create         IS '创建时间';
COMMENT ON COLUMN sys.sys_user.gmt_modify         IS '最后修改时间';
COMMENT ON COLUMN sys.sys_user.flag_delete        IS '逻辑删除标识 (1:已删除, 0:未删除)';
COMMENT ON COLUMN sys.sys_user.pass               IS '限制开关';
COMMENT ON COLUMN sys.sys_user.create_by          IS '创建人';
COMMENT ON COLUMN sys.sys_user.modify_by          IS '最后修改人';

-- ---------------------------------------------------------------------
-- 4. 模拟 ON UPDATE CURRENT_TIMESTAMP(6)：只刷新 gmt_modify，gmt_create 不变
-- ---------------------------------------------------------------------
CREATE OR REPLACE FUNCTION sys.fn_sys_user_set_gmt_modify()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    NEW.gmt_modify := CURRENT_TIMESTAMP(6);
    RETURN NEW;
END;
$$;

-- 触发器无 IF NOT EXISTS 语法，用存在性判断保证幂等
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_trigger
         WHERE tgname = 'trg_sys_user_set_gmt_modify'
           AND tgrelid = 'sys.sys_user'::regclass
    ) THEN
        CREATE TRIGGER trg_sys_user_set_gmt_modify
            BEFORE UPDATE ON sys.sys_user
            FOR EACH ROW
            EXECUTE FUNCTION sys.fn_sys_user_set_gmt_modify();
    END IF;
END $$;

-- ---------------------------------------------------------------------
-- 5. 收敛校验：表、列数、主键、唯一约束、identity、触发器、函数、注释
-- ---------------------------------------------------------------------
DO $$
DECLARE
    tbl_cnt  INT;
    col_cnt  INT;
    pk_cnt   INT;
    uk_cnt   INT;
    idn_ok   INT;
    trg_cnt  INT;
    fn_cnt   INT;
    bad_src  INT;
    cmt_cnt  INT;
BEGIN
    SELECT count(*) INTO tbl_cnt
      FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace
     WHERE n.nspname = 'sys' AND c.relname = 'sys_user' AND c.relkind = 'r';
    IF tbl_cnt <> 1 THEN
        RAISE EXCEPTION 'V74: 表 sys.sys_user 未创建成功';
    END IF;

    SELECT count(*) INTO col_cnt
      FROM information_schema.columns
     WHERE table_schema = 'sys' AND table_name = 'sys_user';
    IF col_cnt <> 24 THEN
        RAISE EXCEPTION 'V74: sys.sys_user 列数为 %，预期 24', col_cnt;
    END IF;

    SELECT count(*) INTO pk_cnt
      FROM pg_constraint
     WHERE conname = 'pk_sys_user'
       AND conrelid = 'sys.sys_user'::regclass
       AND contype = 'p';
    IF pk_cnt <> 1 THEN
        RAISE EXCEPTION 'V74: sys.sys_user 缺少主键 pk_sys_user(idn)';
    END IF;

    SELECT count(*) INTO uk_cnt
      FROM pg_constraint
     WHERE conrelid = 'sys.sys_user'::regclass
       AND contype = 'u'
       AND conname IN ('uk_sys_user_email', 'uk_sys_user_mobile');
    IF uk_cnt <> 2 THEN
        RAISE EXCEPTION 'V74: sys.sys_user 唯一约束缺失（实际 %，预期 2：email / mobile_phone_no）', uk_cnt;
    END IF;

    SELECT count(*) INTO idn_ok
      FROM information_schema.columns
     WHERE table_schema = 'sys' AND table_name = 'sys_user'
       AND column_name = 'idn' AND is_identity = 'YES' AND data_type = 'bigint';
    IF idn_ok <> 1 THEN
        RAISE EXCEPTION 'V74: sys.sys_user.idn 不是 bigint identity 列';
    END IF;

    SELECT count(*) INTO trg_cnt
      FROM pg_trigger
     WHERE tgname = 'trg_sys_user_set_gmt_modify'
       AND tgrelid = 'sys.sys_user'::regclass;
    IF trg_cnt <> 1 THEN
        RAISE EXCEPTION 'V74: sys.sys_user 缺少触发器 trg_sys_user_set_gmt_modify';
    END IF;

    SELECT count(*) INTO fn_cnt
      FROM pg_proc p
      JOIN pg_namespace n ON n.oid = p.pronamespace
     WHERE n.nspname = 'sys' AND p.proname = 'fn_sys_user_set_gmt_modify';
    IF fn_cnt = 0 THEN
        RAISE EXCEPTION 'V74: 函数 sys.fn_sys_user_set_gmt_modify 未创建成功';
    END IF;

    -- 语义守住：创建时间只在插入时生成，更新不得改写 gmt_create
    SELECT count(*) INTO bad_src
      FROM pg_proc p
      JOIN pg_namespace n ON n.oid = p.pronamespace
     WHERE n.nspname = 'sys'
       AND p.proname = 'fn_sys_user_set_gmt_modify'
       AND position('NEW.gmt_create' in p.prosrc) > 0;
    IF bad_src > 0 THEN
        RAISE EXCEPTION 'V74: 触发器函数不得改写 gmt_create（创建时间只在插入时生成）';
    END IF;

    SELECT count(*) INTO cmt_cnt
      FROM pg_description
     WHERE objoid = 'sys.sys_user'::regclass
       AND objsubid BETWEEN 0 AND 24;
    IF cmt_cnt <> 25 THEN
        RAISE EXCEPTION 'V74: sys.sys_user 注释数为 %，预期 25（表 + 24 列）', cmt_cnt;
    END IF;

    RAISE NOTICE 'V74: 校验通过（sys.sys_user 就绪，24 列、主键/唯一约束/identity/触发器/注释齐备）';
END $$;

COMMIT;
